import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { createContractProcedureBuilder } from "../errors";

// Dashboard stats output schema
const dashboardStatsSchema = z
  .object({
    totalUniversities: z.number().int().nonnegative(),
    totalUsers: z.number().int().nonnegative(),
  })
  .strict();

const universityInsightsSchema = z
  .object({
    totals: z
      .object({
        total: z.number().int().nonnegative(),
        public: z.number().int().nonnegative(),
        private: z.number().int().nonnegative(),
        withWebsite: z.number().int().nonnegative(),
      })
      .strict(),
    averages: z
      .object({
        admitRateOverall: z.number().min(0).max(1).nullable(),
      })
      .strict(),
    stateDistribution: z
      .array(
        z
          .object({
            state: z.string().length(2),
            count: z.number().int().nonnegative(),
          })
          .strict(),
      )
      .max(50),
    recentUpdates: z
      .array(
        z
          .object({
            month: z.string().min(1),
            label: z.string().min(1),
            count: z.number().int().nonnegative(),
          })
          .strict(),
      )
      .max(24),
    admitRateDistribution: z
      .array(
        z
          .object({
            label: z.string().min(1),
            count: z.number().int().nonnegative(),
          })
          .strict(),
      )
      .max(10),
  })
  .strict();

// Contract definition
const contractProcedure = createContractProcedureBuilder();

export const statsContract = {
  getDashboardStats: contractProcedure
    .input(z.void())
    .output(dashboardStatsSchema),
  getUniversityInsights: contractProcedure
    .input(z.void())
    .output(universityInsightsSchema),
};

export type StatsContract = typeof statsContract;
export type StatsContractInputs = InferContractRouterInputs<StatsContract>;
export type StatsContractOutputs = InferContractRouterOutputs<StatsContract>;

// Type exports for easier usage
export type DashboardStatsOutput = StatsContractOutputs["getDashboardStats"];
export type UniversityInsightsOutput =
  StatsContractOutputs["getUniversityInsights"];
